{
  "organization": {
    "name": "罗德岛 (Rhodes Island, ロドス・アイランド)",
    "type": ["制药公司", "建筑公司"],
    "leader":  ["博士","阿米娅"],
    "brief": "罗德岛制药公司，本部为一座大型陆行舰，是一个注册时间并不长，拥有完整武装力量和制药、科研技术的制药公司，专注于对矿石病病人的治疗。虽然罗德岛公司一直在制药，但是并没有公开卖药。与此同时，罗德岛也在致力于创建感染者与非感染者和平共处的社会，以及解决感染者引发的各种事件，抗击极端感染者组织整合运动。虽然罗德岛并没有成功研发出彻底治愈矿石病的技术，但是在罗德岛的努力下，许多感染者的病情都得到了控制。"
  },
  "members": {
    "ceo":  ["博士","阿米娅"],
    "neurology_doctor_and_field_commander": "博士",
    "medical_department": {
      "director": "凯尔希（兼 特殊护卫队 宪兵队 ‘S.W.E.E.P原型’管理者）",
      "doctors": ["安托（已殉职）", "嘉维尔", "安赛尔", "芙蓉", "苏苏洛", "亚叶", "末药", "白面鸮", "Medic"],
      "drug_development_team": ["维荻"],
      "other_staff": ["闪灵", "阿"]
    },
    "engineering_department": {
      "chief_engineer": "可露希尔",
      "subordinates": ["温蒂", "森蚺", "瑕光", "格雷伊", "休谟斯", "空构（访学人员）", "青枳", "杏仁"]
    },
    "mechanics": ["Mechanist"],
    "blood_bank_manager": "华法琳",
    "instructors": {
      "chief_instructor": "杜宾",
      "vanguard_instructor": "格瑞斯",
      "heavy_instructor": ["法伦", "坚雷"],
      "sniper_instructor": "苔丝",
      "caster_instructor": "维克多",
      "medical_instructor": "丽雅",
      "guard_instructor": "鞭刃"
    },
    "legal_advisors": ["但书", "斥罪"],
    "elite_operators": ["ACE（已殉职）", "Scout（已殉职）", "迷迭香", "煌", "术髓", "锋刃", "风暴眼", "触痕", "Misery", "Raidian", "Outcast（已殉职）", "Logos", "Mechanist", "Whitesmith（已殉职）"],
    "operations_detachment_a4": {
      "leader": "夜刀",
      "members": ["巡林者", "黑角", "杜林"]
    },
    "agor_affairs_responsible_person": "歌蕾蒂娅",
    "iberia_affairs_responsible_person": "郁金香",
    "victoria_office": {
      "hillshire": ["琴柳", "奥利弗", "碎纸机", "威尔"],
      "londinium": ["海蒂"],
      "brentwood": ["刺玫"],
      "others": ["戴菲恩"]
    },
    "caspian_office": ["临光"],
    "surakarta_office": ["直尺"],
    "leithania_office": {
      "zwillingstuermes_sunset_district": ["行板", "车尔尼"],
      "others": ["活塞", "菲勒加斯"]
    },
    "sargon_long_spring_town_office": ["奥克芬（安全屋看门人）"],
    "bolivar_office": ["晓歌"],
    "columbia_davytown_office": ["杰西卡"],
    "sweep_committee": {
      "founder": "凯尔希",
      "responsible_person": "阿斯卡纶",
      "members": ["红", "清道夫", "白金", "狮蝎"]
    }
  },
  "ship_overview": {
    "description": "罗德岛不仅仅是组织名称，也是作为总部所在的大型陆行舰的名字。该舰是由雷姆必拓的矿业公司协助发掘出来的旧时代遗物，整体舰只相当于一座移动城邦的地块，但因其立体化的结构，使得这艘舰船可以承载比一般小型移动城邦更多的人员，包括驻舰的协力人士与罗德岛收治的矿石病患者。罗德岛舰内的生活设施充足，包括干员宿舍、大型医疗机构、培训干员的训练场、小型商店街以及组织下辖的各个部门，如工程部、人事部等等。罗德岛内甚至有一家名为‘再来一杯’的酒吧，仅于晚间9:00到10:00内供应酒精饮料。",
    "dimensions": {
      "length": "600米",
      "width": "306米",
      "height": "136米",
      "weight": "130000吨"
    },
    "speed": "最高航速80千米/小时",
    "armament": "无武装",
    "special_facilities": ["石棺（家用生理修复仪）"],
    "transport": {
      "land": "对外运输主要以陆路为主，可以将一般民用开车开入舰船",
      "air": "有甲板和停机坪以供飞行器起落"
    }
  }
}

